@input_guard
def solve_tril_mix(
    A: torch.Tensor,
    cu_seqlens: torch.Tensor | None = None,
    chunk_indices: torch.LongTensor | None = None,
    output_dtype: torch.dtype = torch.float,
    use_manual_scope: bool = True,
) -> torch.Tensor:
    """
    Compute the inverse of the matrix I + A
    A should be strictly lower triangular, i.e., A.triu() == 0.

    Args:
        A (torch.Tensor):
            [B, T, H, BT], where BT should only be 16, 32, or 64.
        cu_seqlens (torch.Tensor):
            The cumulative sequence lengths of the input tensor. Default: `None`.
        output_dtype (torch.dtype):
            The dtype of the output tensor. Default: `torch.float`.
            If `None`, the output dtype will be the same as the input dtype.

    Returns:
        (I + A)^-1 with the same shape as A
    """
    assert A.shape[-1] in [16, 32, 64]
    output_dtype = A.dtype if output_dtype is None else output_dtype

    B, T, H, BT = A.shape
    if chunk_indices is None and cu_seqlens is not None:
        chunk_indices = prepare_chunk_indices(cu_seqlens, BT)
    NT = len(chunk_indices) if cu_seqlens is not None else triton.cdiv(T, BT)

    Ai = torch.zeros_like(A, dtype=output_dtype)
    if BT == 16:
        merge_fn = solve_tril_16x16_kernel
    elif BT == 32:
        merge_fn = merge_16x16_to_32x32_inverse_kernel
    elif BT == 64:
        merge_fn = (merge_16x16_to_64x64_inverse_kernel_mix
                    if use_manual_scope else merge_16x16_to_64x64_inverse_kernel)

    result_path = "./result_profiling"
    skip_first = 10
    wait = 0
    warmup = 3
    active = 30
    repeat = 1
    stream = torch.npu.current_stream()
    experimental_config = torch_npu.profiler._ExperimentalConfig(
        aic_metrics=torch_npu.profiler.AiCMetrics.PipeUtilization,
        profiler_level=torch_npu.profiler.ProfilerLevel.Level1,
        l2_cache=False,
        data_simplification=False,
    )
    with torch_npu.profiler.profile(
            activities=[
                torch_npu.profiler.ProfilerActivity.CPU,
                torch_npu.profiler.ProfilerActivity.NPU,
            ],
            schedule=torch_npu.profiler.schedule(
                wait=wait,
                warmup=warmup,
                active=active,
                repeat=repeat,
                skip_first=skip_first,
            ),
            on_trace_ready=torch_npu.profiler.tensorboard_trace_handler(result_path),
            record_shapes=True,
            profile_memory=False,
            with_stack=False,
            with_flops=False,
            with_modules=False,
            experimental_config=experimental_config,
    ) as prof:
        stream.synchronize()
        for _ in range(skip_first + (wait + warmup + active) * repeat):
            merge_fn[NT, B * H](
                A=A,
                Ai=Ai,
                cu_seqlens=cu_seqlens,
                chunk_indices=chunk_indices,
                T=T,
                H=H,
                BT=BT,
                USE_TMA=False,
                DOT_PRECISION="ieee",
                # force_simt_only=True,
                compile_mode="simd_simt",
            )
            prof.step()
        stream.synchronize()

    merge_fn[NT, B * H](
        A=A,
        Ai=Ai,
        cu_seqlens=cu_seqlens,
        chunk_indices=chunk_indices,
        T=T,
        H=H,
        BT=BT,
        USE_TMA=False,
        DOT_PRECISION="ieee",
        # force_simt_only=True,
        compile_mode="simd_simt",
    )
    return Ai


def naive_chunk_scaled_dot_kkt_fwd(
    k: torch.Tensor,
    g: torch.Tensor | None = None,
    beta: torch.Tensor | None = None,
    chunk_size: int = 64,
    cu_seqlens: torch.Tensor | None = None,
):
    B, T, H, K = k.shape
    HV = beta.shape[2] if beta is not None else H
    orig_dtype = k.dtype

    k = k.to(torch.float32)
    if g is not None:
        g = g.to(torch.float32)
    if beta is not None:
        beta = beta.to(torch.float32)

    A = torch.zeros(B, T, HV, chunk_size, dtype=torch.float32, device=k.device)

    N = cu_seqlens.shape[0] - 1
    for i_n in range(N):
        bos = cu_seqlens[i_n].item()
        eos = cu_seqlens[i_n + 1].item()
        seq_len = eos - bos
        NT_seq = (seq_len + chunk_size - 1) // chunk_size

        for i_t in range(NT_seq):
            s = bos + i_t * chunk_size
            e = min(s + chunk_size, eos)
            bt = e - s

            k_chunk = k[:, s:e, :, :]

            for h in range(HV):
                k_h = k_chunk[:, :, h // (HV // H), :]
                b_A = torch.matmul(k_h, k_h.transpose(-1, -2))

                if g is not None:
                    g_chunk = g[:, s:e, h]
                    g_i = g_chunk.unsqueeze(-1)
                    g_j = g_chunk.unsqueeze(-2)
                    b_A = b_A * torch.exp(g_i - g_j)

                if beta is not None:
                    beta_chunk = beta[:, s:e, h]
                    b_A = b_A * beta_chunk.unsqueeze(-1)

                mask = torch.tril(torch.ones(bt, bt, device=k.device, dtype=torch.bool), diagonal=-1)
                b_A = b_A * mask

                A[:, s:e, h, :bt] = b_A

    return A.to(orig_dtype)


@pytest.mark.parametrize(
    ("B", "T", "H", "chunk_size"),
    [
        pytest.param(*test, id="B{}-T{}-H{}-chunk_size{}".format(*test)) for test in [
            (1, 1024, 32, 64),
            (1, 1024, 64, 64),
            (8, 1024, 32, 64),
            (16, 1024, 64, 64),
            (1, 8192, 64, 64),
            (8, 8192, 32, 64),
            (16, 8192, 64, 64),
            (4, 131072, 32, 64),
        ]
    ],
)
def test_solve_tril(B, T, H, chunk_size):
    device = "npu"
    # do not randomly intiialize A otherwise the inverse is not stable
    k = F.normalize(torch.randn((B, H, T, 64), dtype=torch.float32, device=device), dim=-1)
    # Pad the second-to-last dimension (T) to be a multiple of chunk_size
    padding_size = (chunk_size - T % chunk_size) % chunk_size
    k_padded = F.pad(k, (0, 0, 0, padding_size, 0, 0, 0, 0))
    k_padded = k_padded.reshape(B, H, -1, chunk_size, 64)
    A = (k_padded @ k_padded.transpose(-1, -2)).tril(-1)

    ref = torch.inverse(A + torch.eye(A.shape[-1], device=A.device)[None, None, None, ...])
    ref = ref.reshape(B, H, -1, chunk_size)[:, :, :T, :]
    print(ref)

    tri = solve_tril_simt(A.reshape(B, H, -1, chunk_size)[:, :, :T, :].transpose(1, 2)).transpose(1, 2)

    #tri = solve_tril_mix(A.reshape(B, H, -1, chunk_size)[:, :, :T, :].transpose(1, 2)).transpose(1, 2)
    print(tri)

    assert_close("solve_tril", ref, tri, 0.0001)


